	case STATE_FOLLOW:
		aiState = new CAiSFollow();
		aiState->Reset(STATE_FOLLOW);
		break;
	case STATE_BREACH:
		aiState = new CAiSBreach();
		aiState->Reset(STATE_BREACH);
		break;
